qualified_questions.sparql_query:
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?version
WHERE {
    dcterms:PhysicalMedium dcterms:hasVersion ?version .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?version
WHERE {
    dcterms:Policy dcterms:hasVersion ?version .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource
WHERE {
    ?resource rdf:type dcterms:PhysicalResource .
    FILTER NOT EXISTS { 
        ?resource dcterms:medium ?medium .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?policy ?physicalResource ?medium ?subject
WHERE {
    ?policy rdf:type dcterms:Policy .
    ?physicalResource rdf:type dcterms:PhysicalResource .
    OPTIONAL { ?physicalResource dcterms:medium ?medium . }
    OPTIONAL { ?physicalResource dc:subject ?subject . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?physicalResource ?physicalMedium
WHERE {
    ?physicalResource rdf:type dcterms:PhysicalResource .
    ?physicalMedium rdf:type dcterms:PhysicalMedium .
    FILTER NOT EXISTS {
        ?x rdf:type dcterms:PhysicalResource ;
           rdf:type dcterms:PhysicalMedium .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?physicalResource ?type ?policyImplications
WHERE {
    ?physicalResource rdf:type dcterms:PhysicalResource .
    ?physicalResource dcterms:subject ?subject .
    ?physicalResource dcterms:medium ?medium .
    OPTIONAL { 
        ?physicalResource rdf:type ?type . 
    }
    OPTIONAL { 
        ?policy rdf:type dcterms:Policy .
        ?policy dcterms:hasVersion ?version .
        BIND(?version AS ?policyImplications)
    }
    FILTER NOT EXISTS {
      ?physicalResource a ?type .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?class
WHERE {
    { ?class rdf:type owl:Class ; rdfs:label "Policy"@en }
    UNION
    { ?class rdf:type owl:Class ; rdfs:label "PhysicalMedium"@en }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?significance
WHERE {
    dcterms:subject dcterms:hasVersion <http://dublincore.org/usage/terms/history/#subjectT-002> .
    OPTIONAL { dcterms:subject rdfs:comment ?significance . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?dcterms_format ?dc_format
WHERE {
    ?resource dcterms:medium ?dcterms_format .
    OPTIONAL { ?resource dc:format ?dc_format . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?resource ?format ?medium
WHERE {
    ?resource rdf:type dcterms:PhysicalResource .
    OPTIONAL { ?resource dcterms:format ?format . }
    OPTIONAL { ?resource dcterms:medium ?medium . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?relation ?value
WHERE {
    dcterms:accrualPeriodicity ?property ?value .
    OPTIONAL { dcterms:accrualPeriodicity rdfs:domain ?relation }
    OPTIONAL { dcterms:accrualPeriodicity rdfs:range ?relation }
    OPTIONAL { dcterms:accrualPeriodicity rdf:type ?relation }
    OPTIONAL { dcterms:accrualPeriodicity rdfs:isDefinedBy ?relation }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?characteristic
WHERE {
    {
        ?characteristic rdfs:range dcterms:RightsStatement .
        FILTER NOT EXISTS { 
            ?characteristic rdfs:range ?other .
            FILTER (?other != dcterms:LicenseDocument)
        }
    }
    UNION
    {
        ?characteristic rdfs:range dcterms:LicenseDocument .
        FILTER NOT EXISTS { 
            ?characteristic rdfs:range ?other .
            FILTER (?other != dcterms:RightsStatement)
        }
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?resource ?accessRight
WHERE {
    ?resource dcterms:accessRights ?accessRight .
    FILTER EXISTS { 
        ?accessRight rdf:type/rdfs:subClassOf* dcterms:RightsStatement 
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT DISTINCT ?property ?type
WHERE {
    { ?property rdf:type owl:ObjectProperty }
    UNION
    { ?property rdf:type owl:AnnotationProperty }
    UNION
    { ?property rdf:type owl:DatatypeProperty }
    ?property rdfs:isDefinedBy ?definedBy .
    FILTER (strstarts(str(?definedBy), str(dcterms:)))
    BIND(rdf:type AS ?type)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?version
WHERE {
    dcterms:MediaType dcterms:hasVersion ?version .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?type
WHERE {
    :DiagnosisType rdf:type ?type .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?contributor
WHERE {
    ?resource dcterms:contributor ?contributor .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX : <http://example.org/>

SELECT ?purpose
WHERE {
    :isClinicalRecordOf rdf:type owl:ObjectProperty .
    OPTIONAL { :isClinicalRecordOf rdfs:comment ?purpose . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX : <http://example.org/>

SELECT ?property ?object
WHERE {
    { 
        :DiagnosisType rdf:type ?property .
    } UNION {
        :DiagnosisType rdfs:subClassOf ?object .
    } UNION {
        :isClinicalRecordOf owl:inverseOf ?property .
        BIND(:hasClinicalRecord AS ?property)
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource ?diagnosisType
WHERE {
    ?resource :isClinicalRecordOf ?clinicalRecord .
    ?clinicalRecord rdf:type :DiagnosisType .
    OPTIONAL { ?clinicalRecord rdfs:label ?diagnosisType . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?resource
WHERE {
    ?resource rdf:type ?type .
    FILTER NOT EXISTS { ?resource dc:contributor ?contributor }
    FILTER NOT EXISTS { ?resource dcterms:MediaType ?mediaType }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource ?mediaType ?clinicalRecord ?diagnosisType
WHERE {
    ?resource dcterms:MediaType ?mediaType .
    ?resource :isClinicalRecordOf ?clinicalRecord .
    ?clinicalRecord rdf:type :DiagnosisType .
    OPTIONAL { 
        ?clinicalRecord :hasDiagnosisType ?diagnosisType . 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?location ?period
WHERE {
    dcterms:coverage rdfs:range ?range .
    FILTER (?range = dcterms:LocationPeriodOrJurisdiction) .
    BIND(<http://dublincore.org/usage/terms/history/#coverageT-001> AS ?term) .
    OPTIONAL { 
        ?resource dcterms:coverage ?term ;
                 dcterms:coverage ?location .
        FILTER (?location != ?term)
    } .
    OPTIONAL { 
        ?resource dcterms:coverage ?term ;
                 dcterms:coverage ?period .
        FILTER (?period != ?term)
    }
    FILTER(EXISTS {
      [] dcterms:coverage ?term
    })
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?references ?replaces 
WHERE {
    dcterms:references rdfs:subPropertyOf ?superProperty1 .
    dcterms:replaces rdfs:subPropertyOf ?superProperty2 .
    OPTIONAL { dcterms:references rdfs:comment ?referencesComment . }
    OPTIONAL { dcterms:replaces rdfs:comment ?replacesComment . }
    BIND(COALESCE(?referencesComment, "No comment available") AS ?references)
    BIND(COALESCE(?replacesComment, "No comment available") AS ?replaces)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT ?relation
WHERE {
    { dcterms:replaces rdfs:subPropertyOf ?relation }
    UNION
    { dcterms:isRequiredBy rdfs:subPropertyOf ?relation }
    UNION
    { dcterms:references rdfs:subPropertyOf ?relation }
    UNION
    { dcterms:hasVersion rdfs:subPropertyOf ?relation }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?resource ?version
WHERE {
    ?resource dcterms:references ?version .
    FILTER EXISTS { 
        ?version rdfs:subPropertyOf* ?superProperty . 
        ?superProperty rdfs:subPropertyOf dc:relation 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource ?version
WHERE {
    ?resource dcterms:hasVersion ?version .
    FILTER NOT EXISTS {
        ?newVersion dcterms:replaces ?version .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource1 ?resource2
WHERE {
    ?resource1 dcterms:replaces ?resource2 .
    OPTIONAL { 
        ?resource2 dcterms:isRequiredBy ?x .
        FILTER (?x = ?resource1)
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?resource ?isPartOf ?isFormatOf
WHERE {
    ?resource dcterms:isPartOf ?isPartOf .
    OPTIONAL { 
        ?resource dcterms:isFormatOf ?isFormatOf . 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?relation
WHERE {
    { ?relation rdfs:subPropertyOf dc:relation }
    UNION
    { ?relation rdfs:subPropertyOf dcterms:relation }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?resource ?status
WHERE {
    ?resource dcterms:isReplacedBy ?replacedBy .
    OPTIONAL { ?resource rdfs:comment ?status . }
    FILTER(EXISTS { ?resource rdf:type ?type })
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?resource ?relatedResource
WHERE {
    {
        ?resource dcterms:isPartOf ?relatedResource .
    } UNION {
        ?resource dcterms:isFormatOf ?relatedResource .
    } UNION {
        ?resource dcterms:requires ?relatedResource .
    } UNION {
        ?resource dcterms:hasFormat ?relatedResource .
    } UNION {
        ?resource dcterms:isReplacedBy ?relatedResource .
    }
    FILTER (?resource != ?relatedResource)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?resource ?characteristic
WHERE {
    ?resource dcterms:isPartOf ?part .
    OPTIONAL { ?resource dc:relation ?relation . }
    OPTIONAL { ?resource dcterms:requires ?requirement . }
    OPTIONAL { ?resource dcterms:hasFormat ?format . }
    OPTIONAL { ?resource dcterms:isReplacedBy ?replacement . }
    OPTIONAL { ?resource dcterms:isFormatOf ?formatOf . }

    BIND(COALESCE(?part, ?relation, ?requirement, ?format, ?replacement, ?formatOf) AS ?characteristic)
    FILTER (?characteristic != "")
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?standard ?version 
WHERE {
    ?x dcterms:conformsTo ?standard .
    OPTIONAL { ?standard dcterms:hasVersion ?version . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property ?type
WHERE {
    { 
        ?property rdf:type owl:AnnotationProperty .
        ?property rdfs:isDefinedBy <http://purl.org/dc/terms/> .
        BIND("AnnotationProperty" AS ?type)
    } UNION {
        ?property rdf:type owl:ObjectProperty .
        ?property rdfs:isDefinedBy <http://purl.org/dc/terms/> .
        BIND("ObjectProperty" AS ?type)
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vann: <http://purl.org/vocab/vann/>

SELECT ?resource ?standard
WHERE {
    ?resource dcterms:conformsTo ?standard .
    FILTER (EXISTS { 
        ?standard rdf:type ?type . 
        FILTER (?type = owl:Thing) 
    })
    OPTIONAL { 
        ?resource dcterms:isReferencedBy ?reference .
        ?reference dcterms:hasVersion ?version .
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    { 
        ?property rdfs:subPropertyOf dcterms:relation .
    } UNION {
        ?property rdfs:subPropertyOf dc:source .
    }
    FILTER((?property = dcterms:source) || (?property = dcterms:isReferencedBy))
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?resource
WHERE {
    {
        ?resource dcterms:isReferencedBy ?otherResource .
    }
    UNION
    {
        ?resource dcterms:hasPart ?part .
    }
    OPTIONAL { 
        ?resource dcterms:conformsTo ?standard .
    }
    OPTIONAL { 
        ?resource dcterms:hasVersion ?version .
    }
    FILTER NOT EXISTS { ?resource rdf:type owl:Class }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?version
WHERE {
    dcterms:Location dcterms:hasVersion ?version .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
    dcterms:Location rdfs:isDefinedBy ?definition .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?version
WHERE {
    dcterms:RFC1766 dcterms:hasVersion ?version .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?location ?version1 ?version2
WHERE {
    ?location dcterms:hasVersion ?version1 .
    ?location dcterms:hasVersion ?version2 .
    FILTER (?version1 != ?version2) .
    VALUES ?location {dcterms:Location}
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?namespace
WHERE {
    dcterms:Location rdfs:isDefinedBy ?namespace .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?location ?context
WHERE {
    ?location rdf:type dcterms:Location .
    OPTIONAL { ?location rdfs:isDefinedBy ?definition . }
    OPTIONAL { ?location rdfs:seeAlso ?seeAlso . }
    FILTER (?location = dcterms:RFC1766)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?range
WHERE {
    dcterms:mediator rdfs:range ?range.
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT ?entity ?relation
WHERE {
    {
        ?class rdf:type owl:Class .
        BIND(?class AS ?entity) .
        BIND("Class" AS ?relation) .
    }
    UNION
    {
        ?property rdf:type owl:ObjectProperty .
        BIND(?property AS ?entity) .
        BIND("ObjectProperty" AS ?relation) .
    }
    UNION
    {
        ?property rdf:type owl:AnnotationProperty .
        BIND(?property AS ?entity) .
        BIND("AnnotationProperty" AS ?relation) .
    }
    UNION
    {
        ?class rdfs:subClassOf ?superClass .
        BIND(?class AS ?entity) .
        BIND(CONCAT("Subclass of ", STR(?superClass)) AS ?relation) .
    }
    UNION
    {
        ?property rdfs:subPropertyOf ?superProperty .
        BIND(?property AS ?entity) .
