SELECT ?property ?domain ?range 
WHERE {
    {
        ?property rdf:type owl:DatatypeProperty .
        ?property rdfs:domain ?domain .
        ?property rdfs:range ?range .
    } UNION {
        ?property rdf:type owl:AnnotationProperty .
        ?property rdfs:domain ?domain .
        ?property rdfs:range ?range .
    } UNION {
        ?class rdf:type owl:Class .
        ?class rdfs:subClassOf ?domain .
        ?property rdfs:domain ?domain .
    }
    FILTER (?domain = :GaitData || ?domain = dcterms:BibliographicResource)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?property ?domain
WHERE {
    {
        :walkingSpeed rdfs:domain ?domain .
        BIND(:walkingSpeed AS ?property)
    } UNION {
        :dynamicBalance rdfs:domain ?domain .
        BIND(:dynamicBalance AS ?property)
    } UNION {
        :stepLength rdfs:domain ?domain .
        BIND(:stepLength AS ?property)
    }
    FILTER(?domain = :GaitData)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX : <http://example.org/>

SELECT ?diagnosticPurpose
WHERE {
    :apathyInventory rdfs:seeAlso ?assessment .
    ?assessment rdf:type :NeuropsychiatricAndMoodAssessment .
    OPTIONAL { 
        :apathyInventory :usedFor ?diagnosticPurpose . 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?range ?version
WHERE {
    dcterms:issued rdfs:range ?range .
    dcterms:issued dcterms:hasVersion ?version .
    OPTIONAL { dcterms:issued rdf:type ?property }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?property ?superProperty 
WHERE {
    ?property rdfs:subPropertyOf ?superProperty .
    dcterms:isVersionOf rdfs:subPropertyOf ?superProperty .
    FILTER (?property != dcterms:isVersionOf) .
    VALUES ?property { dcterms:issued dcterms:abstract }
}
